package dev.yz.dnsobserver;
import android.content.Context;import android.os.Bundle;import org.json.*;import java.time.Instant;
/** Pull bounded persisted relay records when UI is open; source UID stays explicitly unknown. */
public final class RootRuntimeRecords {
 public static synchronized void importRows(Context c,JSONArray rows){if(rows==null||!DnsObservationStore.enabled(c))return;android.content.SharedPreferences p=c.getSharedPreferences("runtime_records",0);long since=p.getLong("last_ts",0),max=since;for(int i=0;i<rows.length();i++){try{JSONObject row=rows.getJSONObject(i);long ts=Instant.parse(row.getString("time")).toEpochMilli();if(ts<=since)continue;JSONObject e=row.getJSONObject("event");Bundle b=new Bundle();b.putLong("ts",ts);b.putString("host",e.optString("name"));b.putInt("uid",-1);b.putString("packages","独立 Root DNS · UID 未获取");b.putString("appName","独立 DNS 接管");b.putString("transport",e.optString("transport").toUpperCase(java.util.Locale.ROOT));b.putString("recordKind","PROXY");b.putString("evidence","ROOT_RUNTIME_DNS_RESPONSE");b.putString("dnsType",e.optString("transport"));b.putString("dnsServer",e.optString("upstream"));b.putString("dnsSource",e.optString("evidence"));b.putString("detail","QTYPE="+e.optInt("qtype")+"；客户端="+e.optString("client")+"；上游协议="+e.optString("upstream_transport"));b.putInt("rc",e.optInt("rcode",2));b.putInt("latency",e.optInt("elapsed_ms"));JSONArray ips=e.optJSONArray("ips");String[] addresses=new String[ips==null?0:ips.length()];for(int k=0;k<addresses.length;k++)addresses[k]=ips.optString(k);b.putStringArray("ips",addresses);b.putInt("total",addresses.length);DnsObservationStore.offer(c,b);max=Math.max(max,ts);}catch(Exception ignored){}}if(max>since)p.edit().putLong("last_ts",max).apply();}
}
